ALTER TABLE "appeals" DROP CONSTRAINT "appeals_decision_check";--> statement-breakpoint
ALTER TABLE "learning_assignments" DROP CONSTRAINT "learning_assignments_block_reason_check";--> statement-breakpoint
ALTER TABLE "learning_assignments" DROP CONSTRAINT "learning_assignments_paused_from_check";--> statement-breakpoint
ALTER TABLE "appeals" ADD CONSTRAINT "appeals_decision_check" CHECK ((("appeals"."status" in ('DECIDIDA', 'RECALCULO_PENDENTE', 'ENCERRADA') and "appeals"."decision" is not null and "appeals"."decision" in ('MANTER_RESULTADO', 'ANULAR_ITEM', 'ALTERAR_RESULTADO')) or ("appeals"."status" in ('ABERTA', 'EM_REVISAO') and "appeals"."decision" is null)));--> statement-breakpoint
ALTER TABLE "learning_assignments" ADD CONSTRAINT "learning_assignments_block_reason_check" CHECK ((("learning_assignments"."status" = 'BLOQUEADO' and "learning_assignments"."block_reason" is not null and "learning_assignments"."block_reason" in ('PRE_REQUISITO', 'CONTEUDO_RETIRADO', 'OBJETIVO_EM_REMEDIACAO')) or ("learning_assignments"."status" <> 'BLOQUEADO' and "learning_assignments"."block_reason" is null)));--> statement-breakpoint
ALTER TABLE "learning_assignments" ADD CONSTRAINT "learning_assignments_paused_from_check" CHECK ((("learning_assignments"."status" = 'PAUSADO' and "learning_assignments"."paused_from" is not null and "learning_assignments"."paused_from" in ('NAO_ATRIBUIDO', 'ATRIBUIDO', 'DISPONIVEL', 'EM_ANDAMENTO', 'CONCLUIDO', 'EM_REFORCO', 'CONCLUIDO_COM_RETENCAO_PENDENTE', 'BLOQUEADO')) or ("learning_assignments"."status" <> 'PAUSADO' and "learning_assignments"."paused_from" is null)));